Mögliche Logik, die wahrscheinlich meistens(!) passen würde:

```
import javax.swing.*;
import java.awt.*;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Calendar;

public class DateFormattedTextFieldExample {

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> createAndShowGUI());
    }

    private static void createAndShowGUI() {
        JFrame frame = new JFrame("Formatted Date Field Example");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        JFormattedTextField formattedTextField = createFormattedDateField();
        JPanel panel = new JPanel();
        panel.add(new JLabel("Date:"));
        panel.add(formattedTextField);

        frame.getContentPane().add(panel, BorderLayout.CENTER);
        frame.setSize(300, 200);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    private static JFormattedTextField createFormattedDateField() {
        SimpleDateFormat dateFormat = new SimpleDateFormat("dd.MM.yy");
        dateFormat.setLenient(false);

        JFormattedTextField formattedTextField = new JFormattedTextField(dateFormat);
        formattedTextField.setColumns(10);

        DateFormatter dateFormatter = new DateFormatter(dateFormat);
        formattedTextField.setFormatterFactory(new DefaultFormatterFactory(dateFormatter));

        return formattedTextField;
    }

    // Custom DateFormatter to handle two-digit years
    private static class DateFormatter extends DateFormatter {
        public DateFormatter(SimpleDateFormat format) {
            super(format);
        }

        @Override
        public Object stringToValue(String text) throws ParseException {

            Object value = super.stringToValue(text);

            if (value instanceof java.util.Date) {
                Calendar calendar = Calendar.getInstance();
                calendar.setTime((java.util.Date) value);
                int year = calendar.get(Calendar.YEAR);
                if (year < 100) {

                    if (year >= 50) {
                        year += 1900;
                    } else {
                        year += 2000;
                    }
                    calendar.set(Calendar.YEAR, year);
                    value = calendar.getTime();
                }
            }

            return value;
        }
    }
}

```

